use u_numflow::distributions::{
    BetaDistribution, ChiSquared, GammaDistribution, LogNormal, Normal, Pert, Triangular, Uniform,
};

fn survival(kind: &str, p: &[f64], x: f64) -> f64 {
    match kind {
        "Normal" => Normal::new(p[0], p[1]).expect("valid").survival(x),
        "LogNormal" => LogNormal::new(p[0], p[1]).expect("valid").survival(x),
        "Gamma" => GammaDistribution::new(p[0], p[1])
            .expect("valid")
            .survival(x),
        "ChiSquared" => ChiSquared::new(p[0]).expect("valid").survival(x),
        "Pert" => Pert::with_shape(p[0], p[1], p[2], p[3])
            .expect("valid")
            .survival(x),
        "Uniform" => Uniform::new(p[0], p[1]).expect("valid").survival(x),
        "Triangular" => Triangular::new(p[0], p[1], p[2])
            .expect("valid")
            .survival(x),
        other => panic!("unknown kind {other}"),
    }
}

fn cdf(kind: &str, p: &[f64], x: f64) -> f64 {
    match kind {
        "Normal" => Normal::new(p[0], p[1]).expect("valid").cdf(x),
        "LogNormal" => LogNormal::new(p[0], p[1]).expect("valid").cdf(x),
        "Gamma" => GammaDistribution::new(p[0], p[1]).expect("valid").cdf(x),
        "ChiSquared" => ChiSquared::new(p[0]).expect("valid").cdf(x),
        "Pert" => Pert::with_shape(p[0], p[1], p[2], p[3])
            .expect("valid")
            .cdf(x),
        "Uniform" => Uniform::new(p[0], p[1]).expect("valid").cdf(x),
        "Triangular" => Triangular::new(p[0], p[1], p[2]).expect("valid").cdf(x),
        other => panic!("unknown kind {other}"),
    }
}

/// The upper tail of every distribution that has one, against a 60-digit
/// reference built from the same (exactly representable) inputs: the relative
/// error holds from a tail of 0.99 to one of 10⁻³⁰⁰.
#[test]
fn the_survival_function_matches_a_reference_to_relative_precision() {
    let mut worst = 0.0_f64;
    for &(kind, params, x, want) in ROWS {
        let got = survival(kind, params, x);
        let rel = (got - want).abs() / want;
        worst = worst.max(rel);
        assert!(
            rel <= 1e-12,
            "{kind}{params:?}.survival({x:e}) = {got:e}, reference {want:e} (relative error {rel:e})"
        );
    }
    eprintln!("worst relative error over {} rows: {worst:e}", ROWS.len());
}

/// Where both tails have digits, the CDF and the survival function sum to one.
#[test]
fn the_cdf_and_the_survival_function_sum_to_one_where_both_have_digits() {
    for &(kind, params, x, want) in ROWS {
        if (1e-3..=0.999).contains(&want) {
            let sum = cdf(kind, params, x) + survival(kind, params, x);
            assert!(
                (sum - 1.0).abs() < 1e-13,
                "{kind}{params:?} at {x:e}: {sum}"
            );
        }
    }
}

/// The point of the function: past about 8σ `1 − cdf` is 0 and the tail is
/// still a number.
#[test]
fn the_upper_tail_has_digits_where_one_minus_the_cdf_has_none() {
    let n = Normal::new(0.0, 1.0).expect("valid");
    assert_eq!(1.0 - n.cdf(10.0), 0.0);
    assert!((n.survival(10.0) / 7.619853024160527e-24 - 1.0).abs() < 1e-12);
    let c = ChiSquared::new(2.0).expect("valid");
    // k = 2 is an exponential: S(x) = exp(−x/2).
    assert!((c.survival(200.0) / (-100.0_f64).exp() - 1.0).abs() < 1e-12);
    let g = GammaDistribution::new(1.0, 1.0).expect("valid");
    assert!((g.survival(600.0) / (-600.0_f64).exp() - 1.0).abs() < 1e-12);
}

/// The support's ends and the points outside it.
#[test]
fn the_survival_function_is_one_below_the_support_and_zero_above_it() {
    let below_above: [(&str, &[f64], f64, f64); 5] = [
        ("Uniform", &[-2.0, 6.0], -3.0, 7.0),
        ("Triangular", &[0.0, 1.0, 2.0], -1.0, 3.0),
        ("Pert", &[0.0, 1.0, 2.0, 4.0], -1.0, 3.0),
        ("Gamma", &[2.0, 1.0], -1.0, f64::INFINITY),
        ("ChiSquared", &[3.0], -1.0, f64::INFINITY),
    ];
    for (kind, params, low, high) in below_above {
        assert_eq!(survival(kind, params, low), 1.0, "{kind} below");
        if high.is_finite() {
            assert_eq!(survival(kind, params, high), 0.0, "{kind} above");
        } else {
            assert_eq!(survival(kind, params, high), 0.0, "{kind} at infinity");
        }
    }
    assert_eq!(LogNormal::new(0.0, 1.0).expect("valid").survival(0.0), 1.0);
    assert_eq!(LogNormal::new(0.0, 1.0).expect("valid").survival(-5.0), 1.0);
    let b = BetaDistribution::new(2.0, 3.0).expect("valid");
    assert_eq!(b.survival(0.0), 1.0);
}

/// The stretched Beta's CDF now takes the exact complement of its position:
/// a large λ no longer multiplies the rounding of `1 − t`.
#[test]
fn the_pert_cdf_and_survival_agree_at_a_large_lambda_next_to_the_upper_end() {
    let d = Pert::with_shape(0.0, 2.0, 8.0, 2000.0).expect("valid");
    for x in [5.0_f64, 6.0, 7.0, 7.9] {
        let (c, s) = (d.cdf(x), d.survival(x));
        assert!(
            (c + s - 1.0).abs() < 1e-13,
            "x = {x}: cdf {c} + survival {s}"
        );
    }
}
